# ---------------------------------------------------------------------------
# Infer sandbox name from CWD if under ~/sandboxes/<name>/
# ---------------------------------------------------------------------------

infer_sandbox_name() {
    local cwd
    cwd="$(pwd)"
    if [[ "$cwd" == "${SANDBOXES_DIR}/"* ]]; then
        local relative="${cwd#${SANDBOXES_DIR}/}"
        echo "${relative%%/*}"
        return 0
    fi
    return 1
}

# ---------------------------------------------------------------------------
# Usage
# ---------------------------------------------------------------------------

usage() {
    cat >&2 <<EOF
Usage: $(basename "$0") [OPTIONS] [-- CLAUDE_ARGS...]

Create an OpenShell sandbox running Claude Code in auto mode.

OPTIONS:
    --create NAME     Create sandbox with this name
    --ensure [NAME]   Create sandbox if missing, reconnect if exists (use with --repo/--ref)
    --repo URL        Git repo to clone on host and upload (repeatable)
    --ref REF         Ref for preceding --repo: branch, pr/<num>, tag/<name>, or SHA
    --source-dir DIR  Derive origin URL from local repo checkout
    --add-repo [NAME] Add repo(s) to existing sandbox (use --repo for URL)
    --download [NAME] Download repos from sandbox to ~/sandboxes/<name>/
    --upload [NAME]   Upload local repo changes back into sandbox
    --policy NAME     Policy name or path (e.g. research, work). Standalone: hot-swap on running sandbox
    --profile NAME    Credential profile (e.g. personal). Controls env vars, uploads, and default policy.
                      Only valid with --create, --recreate, or --ensure — applied at build, not after
    --gateway NAME    OpenShell gateway (default: \$OPENSHELL_GATEWAY)
    --refresh [NAME]  Re-upload ~/.claude/, bin/, .bashrc, .env, system prompt
    --recreate [NAME] Download, delete sandbox container, recreate with new image, re-upload repos
    --connect [NAME]  Reconnect to an existing sandbox
    --delete [NAME]   Delete a sandbox and local state

    NAME is optional for commands marked [NAME] when CWD is under ~/sandboxes/<name>/.
    --no-clone        Skip repo cloning (create sandbox with env + config only)
    --list            List sandboxes
    --fetch-service   Start the outbound fetch service, follow its log, stop it on exit
    --dryrun          Print commands instead of running them
    --debug           Show all commands as they run (set -x)
    --help            Show this help

EXAMPLES:
    $(basename "$0") --create nexus --repo git@github.com:org/nexus.git --ref pr/42
    $(basename "$0") --ensure nexus-pr-42 --repo git@github.com:org/nexus.git --ref pr/42
    $(basename "$0") --add-repo nexus --repo git@github.com:org/lib.git --ref v2.0
    $(basename "$0") --add-repo nexus --repo git@github.com:org/ui.git --source-dir ~/source/ui
    $(basename "$0") --download nexus
    $(basename "$0") --upload nexus --repo nexus
    $(basename "$0") --connect nexus
    $(basename "$0") --delete nexus
EOF
    exit "${1:-0}"
}

# ---------------------------------------------------------------------------
# Ensure gws sandbox credentials are valid (interactive — may open browser)
# ---------------------------------------------------------------------------

ensure_gws_creds() {
    command -v gws &>/dev/null || return 0
    local gws_dir="${HOME}/.config/gws-sandbox"
    if [[ -f "${gws_dir}/credentials.enc" ]]; then
        local valid
        valid=$(GOOGLE_WORKSPACE_CLI_CONFIG_DIR="$gws_dir" gws auth status 2>/dev/null | jq -r '.token_valid // false')
        if [[ "$valid" == "true" ]]; then
            echo "gws sandbox credentials valid" >&2
        else
            echo "gws sandbox credentials expired, re-authenticating..." >&2
            GOOGLE_WORKSPACE_CLI_CONFIG_DIR="$gws_dir" gws auth login --scopes "$GWS_SANDBOX_SCOPES"
        fi
    else
        echo "gws sandbox credentials not found, authenticating (readonly)..." >&2
        mkdir -p "$gws_dir"
        if [[ -f "${HOME}/.config/gws/client_secret.json" ]]; then
            cp "${HOME}/.config/gws/client_secret.json" "${gws_dir}/"
        fi
        GOOGLE_WORKSPACE_CLI_CONFIG_DIR="$gws_dir" gws auth login --scopes "$GWS_SANDBOX_SCOPES"
    fi
}

