# Generate PR + Jira context for sandbox repos
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
# Connect to sandbox via exec
# ---------------------------------------------------------------------------

connect_sandbox() {
    local os_name="$1" workdir="$2"
    run exec openshell sandbox exec --name "${os_name}" "${GW_FLAG[@]}" \
        --tty --timeout 0 -- bash -c "(while sleep 30; do printf '\\005' 2>/dev/null; done) & source /sandbox/.bashrc && cd ${workdir} && /sandbox/bin/claude-wrapper.sh"
}

# ---------------------------------------------------------------------------
# Short name for OpenShell (19-char limit from DNS label constraint)
# ---------------------------------------------------------------------------

short_name() {
    local hash
    hash=$(printf '%s' "$1" | md5sum | cut -c1-12)
    echo "sb-${hash}"
}

# Resolve full name → openshell name from manifest
resolve_openshell_name() {
    local name="$1"
    local manifest="${SANDBOXES_DIR}/${name}/manifest.json"
    if [[ -f "$manifest" ]]; then
        local os_name
        os_name=$(jq -r '.openshell_name // empty' "$manifest")
        if [[ -n "$os_name" ]]; then
            echo "$os_name"
            return
        fi
    fi
    # No manifest — fall back to short_name for pre-existing sandboxes
    short_name "$name"
}

# Resolve openshell name → full name by scanning manifests
resolve_full_name() {
    local os_name="$1"
    local manifest
    for manifest in "${SANDBOXES_DIR}"/*/manifest.json; do
        [[ -f "$manifest" ]] || continue
        local stored
        stored=$(jq -r '.openshell_name // empty' "$manifest")
        if [[ "$stored" == "$os_name" ]]; then
            jq -r '.name' "$manifest"
            return
        fi
    done
    echo "$os_name"
}

# ---------------------------------------------------------------------------
# Dry-run wrapper — prints command instead of running it
# ---------------------------------------------------------------------------

run() {
    if [[ "$DRYRUN" == true ]]; then
        echo "[dryrun]: $*" >&2
        # exec would replace process — exit cleanly in dryrun
        if [[ "$1" == "exec" ]]; then
            exit 0
        fi
        return 0
    fi
    "$@"
}

# ---------------------------------------------------------------------------
# Helper functions
